// The Open with menu: the rows that open a world, or one element of it, in a tool, in order, each with the word it says
// when it cannot open now. Pure: a menu draws these rows and decides no word of its own. The rows come from the
// OnlyWorlds tools list (github.com/OnlyWorlds/tools, tools.json format 1, its README's "Open with"), baked into the
// package as OWTools.All (OWTools.cs, generated by codegen/generate_tools.py).
//
// A port of the TypeScript SDK's openersFor and the Python package's openers_for. Their shared fixture,
// openers.fixture.json, is this file's own test (OWOpenersTests), so every package gives the same rows.

using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;
using Newtonsoft.Json.Linq;

namespace OnlyWorlds.Sdk
{
    /// <summary>A tool's <c>open</c> in the tools list: its link templates and what they need first.</summary>
    public sealed class OWToolOpen
    {
        /// <summary>What a person needs first: signed in to the tool with an OnlyWorlds account that holds the world.</summary>
        public const string Account = "account";

        /// <summary>What a person needs first: the world already in the tool on this device.</summary>
        public const string Device = "device";

        private static readonly IReadOnlyList<string> NoSkips = Array.AsReadOnly(new string[0]);

        public OWToolOpen(string world, string element, string needs)
            : this(world, element, needs, null)
        {
        }

        /// <param name="elementSkips">What the element door does not open (<see cref="OWOpeners.ElementMarks"/>' words); null for none.</param>
        public OWToolOpen(string world, string element, string needs, IReadOnlyList<string> elementSkips)
            : this(world, element, needs, elementSkips, null)
        {
        }

        /// <param name="elementSkips">What the element door does not open (<see cref="OWOpeners.ElementMarks"/>' words); null for none.</param>
        /// <param name="elementTypes">The element types the element door opens (<see cref="OWElementTypes.Slugs"/>' words); null for every type.</param>
        public OWToolOpen(string world, string element, string needs, IReadOnlyList<string> elementSkips, IReadOnlyList<string> elementTypes)
            : this(world, element, needs, elementSkips, elementTypes, false)
        {
        }

        /// <param name="elementSkips">What the element door does not open (<see cref="OWOpeners.ElementMarks"/>' words); null for none.</param>
        /// <param name="elementTypes">The element types the element door opens (<see cref="OWElementTypes.Slugs"/>' words); null for every type.</param>
        /// <param name="opensPublic">The links open a public world with nothing signed in (<see cref="OpensPublic"/>); only beside <see cref="Account"/>.</param>
        public OWToolOpen(string world, string element, string needs, IReadOnlyList<string> elementSkips, IReadOnlyList<string> elementTypes,
            bool opensPublic)
        {
            World = world;
            Element = element;
            Needs = needs;
            ElementSkips = elementSkips == null ? NoSkips : Array.AsReadOnly(new List<string>(elementSkips).ToArray());
            ElementTypes = elementTypes == null ? null : Array.AsReadOnly(new List<string>(elementTypes).ToArray());
            OpensPublic = opensPublic;
        }

        /// <summary>The link that opens a world, holding <c>{world}</c> (the world's id); null without one.</summary>
        public string World { get; }

        /// <summary>
        /// The link that opens one element, holding <c>{id}</c> and, if it needs them, <c>{world}</c> and <c>{type}</c>
        /// (the type word); null without one.
        /// </summary>
        public string Element { get; }

        /// <summary>
        /// <see cref="Account"/>, <see cref="Device"/>, or null for nothing. A public page offers those rows, and an
        /// <see cref="Account"/> row only as one that opens nothing ("Needs an account").
        /// <see cref="OWOpeners.For(IReadOnlyList{OWTool}, string, JObject, OWOpenerSurface)"/> refuses any other word.
        /// </summary>
        public string Needs { get; }

        /// <summary>
        /// What the element door does not open, in the lens profile's graph section's words (<see cref="OWOpeners.ElementMarks"/>:
        /// <c>room</c>, <c>hidden</c>, <c>proposed</c>, <c>map_space</c>, <c>reading_aid</c>); empty when it opens every
        /// element, and on a list older than the key. Given the element, the menu leaves the row out for an element that
        /// carries one of them. A word outside the list's, or a skip on a row with no element door, is refused there.
        /// </summary>
        public IReadOnlyList<string> ElementSkips { get; }

        /// <summary>
        /// The element types the element door opens, as type words (<see cref="OWElementTypes.Slugs"/>: <c>character</c>);
        /// null when it opens every type, and on a list older than the key. On an element's menu the row is left out for
        /// an element of another type, world door or not: the tool opens other kinds of element, so its world is not offered
        /// from this one either. The type is read from the address, so no element body is needed; a world's menu reads no
        /// element types. A word outside the 22, an empty list, a repeat, or types on a row with no element door, is refused
        /// there.
        /// </summary>
        public IReadOnlyList<string> ElementTypes { get; }

        /// <summary>
        /// True when the links open a public world for someone not signed in, though <see cref="Needs"/> is
        /// <see cref="Account"/> for a private one: a public page offers the row live instead of "Needs an account".
        /// Anywhere else the row reads as <see cref="Needs"/> says, since only the public page knows the world is public.
        /// False when absent, and on a list older than the key. True beside any other <see cref="Needs"/> is refused there.
        /// </summary>
        public bool OpensPublic { get; }
    }

    /// <summary>The keys of one tools list row that <see cref="OWOpeners"/> reads; the list's other keys are not kept.</summary>
    public sealed class OWTool
    {
        /// <summary>The rung of a row that is offered; <c>built</c> and <c>delisted</c> rows never are.</summary>
        public const string Listed = "listed";

        private static readonly string[] JsonKeys = { "id", "name", "url", "client", "rung", "open" };

        public OWTool(string id, string name, string url, string client, string rung, OWToolOpen open)
        {
            Id = id;
            Name = name;
            Url = url;
            Client = client;
            Rung = rung;
            Open = open;
        }

        /// <summary>The list's id for the tool, the row's <see cref="OWOpener.Id"/> in the menu.</summary>
        public string Id { get; }

        public string Name { get; }

        public string Url { get; }

        /// <summary>The tool's client name (<c>X-OW-Client</c>), which a surface names itself by; null without one.</summary>
        public string Client { get; }

        /// <summary><c>listed</c>, <c>built</c> or <c>delisted</c>; only <see cref="Listed"/> rows are offered.</summary>
        public string Rung { get; }

        /// <summary>How a link opens a world or an element in the tool; null: never offered.</summary>
        public OWToolOpen Open { get; }

        /// <summary>
        /// One row of <c>tools.json</c> as the list serves it (or as a test writes it). Keys this type does not keep are
        /// ignored; a kept key of the wrong JSON type is refused.
        /// </summary>
        /// <exception cref="ArgumentException">Not a tools row: an id or name that is not a string, an open that is not an
        /// object or null, a template or needs that is not a string or null, an opens_public that is not true or false.</exception>
        public static OWTool FromJson(JObject row)
        {
            if (row == null) throw new ArgumentNullException(nameof(row), "OWTool.FromJson: a tools row is an object");
            var id = row["id"];
            var name = row["name"];
            if (id?.Type != JTokenType.String || name?.Type != JTokenType.String)
                throw new ArgumentException("OWTool.FromJson: each tools row is an object with an id and a name", nameof(row));
            var rid = (string)id;
            OWToolOpen open = null;
            var o = row["open"];
            if (o != null && o.Type != JTokenType.Null)
            {
                if (!(o is JObject door)) throw new ArgumentException($"OWTool.FromJson: tool {rid}: open is an object or null", nameof(row));
                open = new OWToolOpen(Text(door, "world", rid, "open."), Text(door, "element", rid, "open."), Text(door, "needs", rid, "open."),
                    Words(door, "element_skips", rid, string.Join(", ", OWOpeners.ElementMarks)),
                    Words(door, "element_types", rid, string.Join(", ", OWElementTypes.Slugs)),
                    Flag(door, "opens_public", rid, "open."));
            }

            return new OWTool(rid, (string)name, Text(row, "url", rid, ""), Text(row, "client", rid, ""), Text(row, "rung", rid, ""), open);
        }

        /// <summary>The rows of a tools list as served: its <c>tools</c> array.</summary>
        public static List<OWTool> FromJson(JArray rows)
        {
            if (rows == null) throw new ArgumentNullException(nameof(rows), "OWTool.FromJson: the tools list's rows are an array");
            var list = new List<OWTool>(rows.Count);
            foreach (var r in rows)
            {
                if (!(r is JObject row))
                    throw new ArgumentException("OWTool.FromJson: each tools row is an object with an id and a name", nameof(rows));
                list.Add(FromJson(row));
            }

            return list;
        }

        private static string Text(JObject o, string key, string row, string path)
        {
            var token = o[key];
            if (token == null || token.Type == JTokenType.Null) return null;
            if (token.Type != JTokenType.String)
                throw new ArgumentException($"OWTool.FromJson: tool {row}: {path}{key} is a string or null", key);
            return (string)token;
        }

        /// <summary>True or false; false when the key is absent. Null, like any other value, is refused (the TypeScript reader's own rule).</summary>
        private static bool Flag(JObject o, string key, string row, string path)
        {
            var token = o[key];
            if (token == null) return false;
            if (token.Type != JTokenType.Boolean)
                throw new ArgumentException($"OWTool.FromJson: tool {row}: {path}{key} is true or false; got {token.ToString(Newtonsoft.Json.Formatting.None)}", key);
            return (bool)token;
        }

        /// <summary>
        /// A list of words, or null when the key is absent or null (an empty list stays empty). Which words, and whether
        /// an empty list is one, is <see cref="OWOpeners"/>' check.
        /// </summary>
        private static List<string> Words(JObject o, string key, string row, string which)
        {
            var token = o[key];
            if (token == null || token.Type == JTokenType.Null) return null;
            var words = new List<string>();
            if (token is JArray list)
            {
                foreach (var w in list)
                {
                    if (w.Type != JTokenType.String) { words = null; break; }
                    words.Add((string)w);
                }
            }
            else words = null;

            if (words == null)
                throw new ArgumentException($"OWTool.FromJson: tool {row}: open.{key} is null or a list of {which}; got {token.ToString(Newtonsoft.Json.Formatting.None)}", key);
            return words;
        }
    }

    /// <summary>What the surface drawing the menu knows of itself and its reader. <see cref="OWOpeners"/> guesses none of it.</summary>
    public sealed class OWOpenerSurface
    {
        /// <summary>A seat in the world, a guest included.</summary>
        public const string Member = "member";

        /// <summary>The signed-out reader of a public page.</summary>
        public const string Public = "public";

        /// <summary>The keys of a surface as JSON, as the shared fixture writes them.</summary>
        public static readonly IReadOnlyList<string> JsonKeys = Array.AsReadOnly(new[] { "tool", "audience", "signed_in", "browser", "phone", "online" });

        /// <summary>The client name of the surface's own tool, when it is a listed tool; its row says "You are here". <c>onlyworlds</c> is the site itself: the site's own row says it.</summary>
        public string Tool { get; set; }

        /// <summary><see cref="Member"/> or <see cref="Public"/>. Required: never guessed.</summary>
        public string Audience { get; set; }

        /// <summary>Whether the reader is signed in; null when the surface cannot know, and then no row says so.</summary>
        public bool? SignedIn { get; set; }

        /// <summary>False in a desktop app or a game, which cannot see the browser's sign-in. Default true.</summary>
        public bool Browser { get; set; } = true;

        /// <summary>True on a phone. Default false.</summary>
        public bool Phone { get; set; }

        /// <summary>
        /// False when the device has no connection; then every row whose link is a web address says "Needs a connection".
        /// Default true.
        /// </summary>
        public bool Online { get; set; } = true;

        /// <summary>
        /// A surface written as JSON, with the shared fixture's snake_case keys (<c>tool</c>, <c>audience</c>,
        /// <c>signed_in</c>, <c>browser</c>, <c>phone</c>, <c>online</c>). A missing <c>audience</c> stays null, and
        /// <see cref="OWOpeners"/> refuses it there.
        /// </summary>
        /// <exception cref="ArgumentException">An unknown key, or a value of the wrong type, named.</exception>
        public static OWOpenerSurface FromJson(JObject surface)
        {
            if (surface == null) throw new ArgumentNullException(nameof(surface), "OWOpenerSurface.FromJson: the surface is an object ({ audience, ... })");
            var s = new OWOpenerSurface();
            foreach (var p in surface.Properties())
            {
                var v = p.Value;
                switch (p.Name)
                {
                    case "tool":
                        if (v.Type != JTokenType.Null && v.Type != JTokenType.String) Fail("surface tool is a client name or null");
                        s.Tool = v.Type == JTokenType.Null ? null : (string)v;
                        break;
                    case "audience":
                        if (v.Type != JTokenType.Null && v.Type != JTokenType.String) Fail($"surface audience is 'member' or 'public'; got {v.ToString(Newtonsoft.Json.Formatting.None)}");
                        s.Audience = v.Type == JTokenType.Null ? null : (string)v;
                        break;
                    case "signed_in":
                        if (v.Type != JTokenType.Null && v.Type != JTokenType.Boolean) Fail("surface signed_in is true, false or null");
                        s.SignedIn = v.Type == JTokenType.Null ? (bool?)null : (bool)v;
                        break;
                    case "browser":
                        if (v.Type != JTokenType.Boolean) Fail("surface browser is a boolean");
                        s.Browser = (bool)v;
                        break;
                    case "phone":
                        if (v.Type != JTokenType.Boolean) Fail("surface phone is a boolean");
                        s.Phone = (bool)v;
                        break;
                    case "online":
                        if (v.Type != JTokenType.Boolean) Fail("surface online is a boolean");
                        s.Online = (bool)v;
                        break;
                    default:
                        Fail($"unknown key '{p.Name}' in the surface. The keys are {string.Join(", ", JsonKeys)}.");
                        break;
                }
            }

            return s;
        }

        private static void Fail(string what) => throw new ArgumentException("OWOpenerSurface.FromJson: " + what, "surface");
    }

    /// <summary>What <see cref="OWOpeners"/> takes beside the surface.</summary>
    public sealed class OWOpenersOptions
    {
        /// <summary>The keys of the options as JSON, as the shared fixture writes them.</summary>
        public static readonly IReadOnlyList<string> JsonKeys = Array.AsReadOnly(new[] { "element" });

        /// <summary>
        /// The element the menu is for, as the surface was served it (the API's body, the mark flat on it): a row whose
        /// door skips a mark it carries is not there. Null: every row, as before. Only for an element's menu, and only the
        /// element the address names: its own <c>id</c>, read as written, is the address's id taken in lowercase. One held
        /// in upper case (the same id but for case) is one no address can name: the menu has no rows, not a refusal; one
        /// that differs by more than case is refused.
        /// </summary>
        public JObject Element { get; set; }

        /// <summary>The options written as JSON, with the shared fixture's keys (<c>element</c>).</summary>
        /// <exception cref="ArgumentException">An unknown key, or an element that is not an object or null, named.</exception>
        public static OWOpenersOptions FromJson(JObject options)
        {
            if (options == null) throw new ArgumentNullException(nameof(options), "OWOpenersOptions.FromJson: the options are an object ({ element })");
            var o = new OWOpenersOptions();
            foreach (var p in options.Properties())
            {
                if (p.Name != "element")
                    throw new ArgumentException($"OWOpenersOptions.FromJson: unknown key '{p.Name}' in the options. The keys are {string.Join(", ", JsonKeys)}.", nameof(options));
                if (p.Value.Type == JTokenType.Null) continue;
                if (!(p.Value is JObject element))
                    throw new ArgumentException("OWOpenersOptions.FromJson: options element is the element as served, an object, or null", nameof(options));
                o.Element = element;
            }

            return o;
        }
    }

    /// <summary>The words a row says when it cannot open now, or says where it lands. Sentence case, exactly.</summary>
    public static class OWOpenerState
    {
        /// <summary>The surface's own tool.</summary>
        public const string YouAreHere = "You are here";

        /// <summary>The device has no connection and the row's link is a web address.</summary>
        public const string NeedsAConnection = "Needs a connection";

        /// <summary>
        /// The reader is the public (signed out) and the tool needs an account: the row opens nothing. The href stays in
        /// the row; a surface draws it as a row that cannot be followed.
        /// </summary>
        public const string NeedsAnAccount = "Needs an account";

        /// <summary>The tool needs an account and the surface is not a browser, which could see its sign-in.</summary>
        public const string OpensInYourBrowser = "Opens in your browser";

        /// <summary>The tool needs the world on this device and the surface is a phone.</summary>
        public const string NeedsTheWorldOnThisPhone = "Needs the world on this phone";

        /// <summary>On an element, a tool with only a world door: the row opens the world.</summary>
        public const string OpensTheWorld = "Opens the world";

        /// <summary>The tool needs an account and the reader, in a browser, is signed out: "Sign in to &lt;name&gt; first".</summary>
        public static string SignInFirst(string name) => "Sign in to " + name + " first";
    }

    /// <summary>One row of the menu.</summary>
    public sealed class OWOpener
    {
        public OWOpener(string id, string name, string href, string state)
        {
            Id = id;
            Name = name;
            Href = href;
            State = state;
        }

        /// <summary><c>onlyworlds</c> for the site's own row, else the tool's id in the list.</summary>
        public string Id { get; }

        /// <summary><c>onlyworlds.com</c>, or the tool's name.</summary>
        public string Name { get; }

        public string Href { get; }

        /// <summary>One of <see cref="OWOpenerState"/>'s words; null when the row opens now and says nothing.</summary>
        public string State { get; }
    }

    /// <summary>The rows of an Open with menu for a world or one element of it.</summary>
    /// <remarks>
    /// <para>
    /// In order: first the site's own row (id <c>onlyworlds</c>, name <c>onlyworlds.com</c>, the world's or the
    /// element's page on www.onlyworlds.com, for every audience, its one word "You are here" when the surface's
    /// <see cref="OWOpenerSurface.Tool"/> is <c>onlyworlds</c> (the site itself), else "Needs a connection" when offline), then
    /// one row per tools row, in the list's order, that is <c>listed</c> and has a door for this kind. <c>tools</c> is
    /// <see cref="OWTools.All"/> or the list as served (<see cref="OWTool.FromJson(JArray)"/>). The address is a reading from
    /// <see cref="OWAddress.ParseLink"/>, the parts as JSON that <see cref="OWAddress.ElementAddress(JObject)"/> takes,
    /// or the world's id with a type word and an id; a lens and a moment on it ride on no href.
    /// </para>
    /// <para>
    /// A row with <c>open</c> null, or with no door for this kind, is not there. On an element, a tool with only a
    /// world door is a row to its world door that says "Opens the world". On an element given as
    /// <see cref="OWOpenersOptions.Element"/>, a row whose <see cref="OWToolOpen.ElementSkips"/> names a mark the element
    /// carries (<see cref="ElementMarks"/>, each read as <see cref="OWGraph.Read"/> reads it) is not there: its door cannot
    /// open it. A world door alone opens the world, so it stays. On an element's menu, a row whose
    /// <see cref="OWToolOpen.ElementTypes"/> is a list that does not hold the address's type word is not there either,
    /// world door or not: the tool opens other kinds of element (read from the address, so no element body is needed; a
    /// world's menu reads no element types). For the <c>public</c> audience (the signed-out reader)
    /// a row whose <c>needs</c> is <c>device</c> is not there, since a visitor's device holds no world of this one's, and
    /// a row whose <c>needs</c> is <c>account</c> is there and says it needs one, unless its
    /// <see cref="OWToolOpen.OpensPublic"/> is true: its links open a public world with nothing signed in, so on a public
    /// page it needs nothing and reads as a live row. Anywhere else the row reads as its <c>needs</c> says.
    /// </para>
    /// <para>
    /// Each row's state, the first that holds: "You are here" for the surface's own tool (its <c>client</c> is
    /// <see cref="OWOpenerSurface.Tool"/>); then, when <see cref="OWOpenerSurface.Online"/> is false, "Needs a
    /// connection" for a row whose href is a web address (scheme <c>http:</c> or <c>https:</c>, in any case; a row whose
    /// link opens an app on the device is unaffected, and the href stays in the row either way); then, for the
    /// <c>public</c> audience, "Needs an account" for a row whose <c>needs</c> is <c>account</c>, whatever
    /// <see cref="OWOpenerSurface.SignedIn"/> says (the href stays in the row; a surface draws it as a row that opens
    /// nothing); then what <c>needs</c> asks of this surface: <c>account</c> outside a browser "Opens in your browser", in a browser signed
    /// out "Sign in to &lt;name&gt; first" (none when
    /// <see cref="OWOpenerSurface.SignedIn"/> is null: a word shows only when the surface knows it is true),
    /// <c>device</c> on a phone "Needs the world on this phone"; then "Opens the world" (a world door on an element: a
    /// sign-in the row needs is the more urgent word); else null.
    /// </para>
    /// <para>
    /// Refuses with <see cref="OWAddressException"/> (its <see cref="OWAddressException.Reason"/>) an address without a
    /// world (<c>no_world</c>) or with a slug or anything else for its id (<c>bad_world</c>), and a type, id or pairing
    /// <see cref="OWAddress.ElementAddress(string, string, string, string, string, int?)"/> refuses. An
    /// <see cref="ArgumentException"/> whose message names it refuses the rest: a kind that is neither, an element's
    /// openers asked of an address with no element, an unknown key on the address, a missing or unknown audience, an
    /// element given for a world's menu or naming another element than the address, a tools row that is not one (a
    /// <c>needs</c>, an <c>element_skips</c> or an <c>element_types</c> word outside the list's format, an empty or repeating
    /// <c>element_types</c>, skips or types on a row with no element door, or <c>opens_public</c> true beside a
    /// <c>needs</c> other than <c>account</c>, included, and a link that opens no app: an
    /// <c>open.world</c> or <c>open.element</c> that does not begin with its scheme, or whose scheme is
    /// <c>javascript</c>, <c>data</c>, <c>vbscript</c>, <c>file</c>, <c>blob</c> or <c>about</c>, in any case, on any
    /// row and either kind of menu). <see cref="OWAddressException"/>
    /// is an <see cref="ArgumentException"/> too: catch it first. An element given whose own id is the address's but held
    /// in upper case is no refusal: no address can name it, so the answer is no rows, given after every check above has
    /// run (a bad tools row is still refused for it).
    /// </para>
    /// </remarks>
    public static class OWOpeners
    {
        /// <summary>The menu of a world.</summary>
        public const string World = "world";

        /// <summary>The menu of one element of a world.</summary>
        public const string Element = "element";

        /// <summary>The site's own row's id.</summary>
        public const string SiteId = "onlyworlds";

        /// <summary>The site's own row's name.</summary>
        public const string SiteName = "onlyworlds.com";

        private static readonly Regex Placeholder = new Regex(@"\{(world|type|id)\}", RegexOptions.CultureInvariant);

        /// <summary>A web address: its scheme is http or https. Read from the row's filled href.</summary>
        private static readonly Regex Web = new Regex(@"^https?:", RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);

        /// <summary>A link's scheme: the letters before its first colon, at its very start.</summary>
        private static readonly Regex Scheme = new Regex(@"^([A-Za-z][A-Za-z0-9+.-]*):", RegexOptions.CultureInvariant);

        /// <summary>Schemes that open no app: a row whose link used one would run what it carries when pressed.</summary>
        private static readonly string[] NoApp = { "javascript", "data", "vbscript", "file", "blob", "about" };

        /// <summary>
        /// The marks an element door may skip (<see cref="OWToolOpen.ElementSkips"/>), the lens profile's graph section's
        /// words for what a lore view leaves an element out by, in its order: <see cref="OWGraphCut.Room"/>,
        /// <see cref="OWGraphCut.Hidden"/>, <see cref="OWGraphCut.Proposed"/>, <see cref="OWGraphCut.MapSpace"/> (a Map, Pin or
        /// Marker; a Zone is content) and <see cref="OWGraphCut.ReadingAid"/>.
        /// </summary>
        public static readonly IReadOnlyList<string> ElementMarks = Array.AsReadOnly(new[]
        {
            OWGraphCut.Room, OWGraphCut.Hidden, OWGraphCut.Proposed, OWGraphCut.MapSpace, OWGraphCut.ReadingAid,
        });

        /// <summary>The rows for an address given as JSON (<c>form</c>, <c>world</c>, <c>type</c>, <c>id</c>, <c>lens</c>, <c>moment</c>).</summary>
        /// <exception cref="OWAddressException">The address is refused; the reason says why.</exception>
        /// <exception cref="ArgumentException">The rest, named; see the class remarks.</exception>
        public static List<OWOpener> For(IReadOnlyList<OWTool> tools, string kind, JObject address, OWOpenerSurface surface)
            => For(tools, kind, address, surface, null);

        /// <summary>The rows for a reading from <see cref="OWAddress.ParseLink"/>.</summary>
        /// <exception cref="OWAddressException">The reading names its world by slug (<c>bad_world</c>), or no world (<c>no_world</c>), or the writer refuses its form, lens or moment.</exception>
        /// <exception cref="ArgumentException">The rest, named; see the class remarks.</exception>
        public static List<OWOpener> For(IReadOnlyList<OWTool> tools, string kind, OWAddressReading address, OWOpenerSurface surface)
            => For(tools, kind, address, surface, null);

        /// <summary>The rows for a world's id, and for an element its type word and id (both null for a world).</summary>
        /// <exception cref="OWAddressException">The parts are refused; the reason says why.</exception>
        /// <exception cref="ArgumentException">The rest, named; see the class remarks.</exception>
        public static List<OWOpener> For(IReadOnlyList<OWTool> tools, string kind, string world, string type, string id, OWOpenerSurface surface)
            => For(tools, kind, world, type, id, surface, null);

        /// <summary>The rows for an address given as JSON, with the options (the element as served); null options for none.</summary>
        /// <exception cref="OWAddressException">The address is refused; the reason says why.</exception>
        /// <exception cref="ArgumentException">The rest, named; see the class remarks.</exception>
        public static List<OWOpener> For(IReadOnlyList<OWTool> tools, string kind, JObject address, OWOpenerSurface surface, OWOpenersOptions options)
        {
            CheckToolsAndKind(tools, kind);
            if (address == null) throw new ArgumentNullException(nameof(address), "OWOpeners.For: the address is an object ({ form, world, type, id }), as OWAddress.ParseLink reads it");
            foreach (var p in address.Properties())
            {
                if (Array.IndexOf(OWAddress.JsonKeys, p.Name) < 0)
                    Fail($"unknown key '{p.Name}' in the address. The keys are {string.Join(", ", OWAddress.JsonKeys)}.", nameof(address));
            }

            // The address's checks are the writer's: the whole address in its own form (the site's when it has none), so
            // a bad form, a slug, a bad type, id, moment or lens refuse as there; then Rows writes the site's page, where
            // a missing world refuses.
            var whole = (JObject)address.DeepClone();
            if (!whole.TryGetValue("form", out var form) || form.Type == JTokenType.Null) whole["form"] = OWAddress.Human;
            OWAddress.ElementAddress(whole);
            return Rows(tools, kind, OWAddress.Part(address, "world"), OWAddress.Part(address, "type"), OWAddress.Part(address, "id"), surface, options);
        }

        /// <summary>The rows for a reading from <see cref="OWAddress.ParseLink"/>, with the options; null options for none.</summary>
        /// <exception cref="OWAddressException">The reading names its world by slug (<c>bad_world</c>), or no world (<c>no_world</c>), or the writer refuses its form, lens or moment.</exception>
        /// <exception cref="ArgumentException">The rest, named; see the class remarks.</exception>
        public static List<OWOpener> For(IReadOnlyList<OWTool> tools, string kind, OWAddressReading address, OWOpenerSurface surface, OWOpenersOptions options)
        {
            CheckToolsAndKind(tools, kind);
            if (address == null) throw new ArgumentNullException(nameof(address), "OWOpeners.For: the address is a reading, as OWAddress.ParseLink reads it");
            OWAddress.ElementAddress(address.Form ?? OWAddress.Human, address.World, address.Type, address.Id, address.Lens, address.Moment);
            return Rows(tools, kind, address.World, address.Type, address.Id, surface, options);
        }

        /// <summary>The rows for a world's id, and for an element its type word and id, with the options; null options for none.</summary>
        /// <exception cref="OWAddressException">The parts are refused; the reason says why.</exception>
        /// <exception cref="ArgumentException">The rest, named; see the class remarks.</exception>
        public static List<OWOpener> For(IReadOnlyList<OWTool> tools, string kind, string world, string type, string id, OWOpenerSurface surface,
            OWOpenersOptions options)
        {
            CheckToolsAndKind(tools, kind);
            return Rows(tools, kind, world, type, id, surface, options);
        }

        /// <summary>
        /// The marks an element carries, in <see cref="ElementMarks"/>' order, each read by the reader
        /// <see cref="OWGraph.Read"/> uses: <see cref="OWRoom.IsRoomElement"/>, <see cref="OWPayload.IsHidden"/>,
        /// <see cref="OWPayload.IsProposedOrInDoubt"/>, the type folded among <see cref="OWGraph.MapSpaceTypes"/>, and
        /// <see cref="OWRoom.IsCharterElement"/>. Empty for one a lore view keeps.
        /// </summary>
        internal static List<string> MarksOf(JObject element)
        {
            var marks = new List<string>();
            if (OWRoom.IsRoomElement(element)) marks.Add(OWGraphCut.Room);
            if (OWPayload.IsHidden(element)) marks.Add(OWGraphCut.Hidden);
            if (OWPayload.IsProposedOrInDoubt(element)) marks.Add(OWGraphCut.Proposed);
            if (element["type"] is JValue t && t.Type == JTokenType.String && Contains(OWGraph.MapSpaceTypes, OWProfileText.Fold((string)t)))
                marks.Add(OWGraphCut.MapSpace);
            if (OWRoom.IsCharterElement(element)) marks.Add(OWGraphCut.ReadingAid);
            return marks;
        }

        private static bool Contains(IReadOnlyList<string> list, string word)
        {
            foreach (var w in list)
            {
                if (w == word) return true;
            }

            return false;
        }

        /// <summary>A non-empty list of distinct type words, each one of <see cref="OWElementTypes.Slugs"/> as written (Ordinal).</summary>
        private static bool AreTypeWords(IReadOnlyList<string> types)
        {
            if (types.Count == 0) return false;
            var seen = new HashSet<string>(StringComparer.Ordinal);
            foreach (var t in types)
            {
                if (t == null || Array.IndexOf(OWElementTypes.Slugs, t) < 0 || !seen.Add(t)) return false;
            }

            return true;
        }

        private static IEnumerable<string> WordsAsWritten(IReadOnlyList<string> words)
        {
            foreach (var w in words) yield return w == null ? "null" : "\"" + w + "\"";
        }

        private static void CheckToolsAndKind(IReadOnlyList<OWTool> tools, string kind)
        {
            if (tools == null) throw new ArgumentNullException(nameof(tools), "OWOpeners.For: tools is the tools list's rows, a list");
            if (kind != World && kind != Element)
                Fail($"kind is 'world' or 'element'; got {(kind == null ? "null" : "\"" + kind + "\"")}", nameof(kind));
        }

        private static List<OWOpener> Rows(IReadOnlyList<OWTool> tools, string kind, string world, string type, string id, OWOpenerSurface surface,
            OWOpenersOptions options)
        {
            // The address's checks are the writer's, so a slug, a missing world and a bad type or id refuse as there.
            var page = OWAddress.ElementAddress(OWAddress.Human, world, type, id);
            world = world.ToLowerInvariant();
            var hasElement = type != null;
            if (kind == Element && !hasElement) Fail("an element's openers need an address with its type and id", "address");
            var values = new Dictionary<string, string>
            {
                ["world"] = world,
                ["type"] = hasElement ? type : string.Empty,
                ["id"] = hasElement ? id.ToLowerInvariant() : string.Empty,
            };

            if (surface == null) throw new ArgumentNullException(nameof(surface), "OWOpeners.For: the surface is an OWOpenerSurface ({ Audience, ... })");
            var audience = surface.Audience;
            if (audience != OWOpenerSurface.Member && audience != OWOpenerSurface.Public)
                Fail($"surface audience is 'member' or 'public'; got {(audience == null ? "null" : "\"" + audience + "\"")}", nameof(surface));
            var tool = surface.Tool;
            bool Offline(string href) => !surface.Online && Web.IsMatch(href);

            var element = options?.Element;
            var marks = new List<string>();
            var unnamed = false;
            if (element != null)
            {
                if (kind != Element) Fail("options element is for an element's menu; a world's menu takes none", nameof(options));
                // The address is a door, so its id is read in either case and taken in lowercase; an element whose own id
                // differs from it by more than case is another element, the caller's mistake, and refused.
                if (!(element["id"] is JValue eid && eid.Type == JTokenType.String && ((string)eid).ToLowerInvariant() == values["id"]))
                    Fail("options element is the element the address names: its id differs", nameof(options));
                // The address profile's rule for the same id reads the element's own id as written: held in upper case it is
                // one no address can name, so no door opens it. That is no mistake and no refusal: the answer is no rows,
                // given only after every other check has run (below), and a surface still draws its mark.
                unnamed = (string)element["id"] != values["id"];                marks = MarksOf(element);
            }

            var site = kind == Element ? page : OWAddress.ElementAddress(OWAddress.Human, world);
            var siteState = tool == SiteId ? OWOpenerState.YouAreHere : Offline(site) ? OWOpenerState.NeedsAConnection : null;
            var rows = new List<OWOpener> { new OWOpener(SiteId, SiteName, site, siteState) };
            foreach (var r in tools)
            {
                if (r == null || r.Id == null || r.Name == null) Fail("each tools row has an id and a name", nameof(tools));
                var open = r.Open;
                if (open == null) continue;
                CheckTemplate(r.Id, "world", open.World);
                CheckTemplate(r.Id, "element", open.Element);
                var needs = open.Needs;
                if (needs != null && needs != OWToolOpen.Account && needs != OWToolOpen.Device)
                    Fail($"tool {r.Id}: open.needs is 'account', 'device' or null; got \"{needs}\"", nameof(tools));
                if (open.OpensPublic && needs != OWToolOpen.Account)
                    Fail($"tool {r.Id}: open.opens_public is true only beside needs 'account'; got needs {(needs == null ? "null" : "\"" + needs + "\"")}", nameof(tools));
                var skips = open.ElementSkips ?? (IReadOnlyList<string>)Array.Empty<string>();
                foreach (var s in skips)
                {
                    if (s == null || !Contains(ElementMarks, s))
                        Fail($"tool {r.Id}: open.element_skips is a list of {string.Join(", ", ElementMarks)}; got {(s == null ? "null" : "\"" + s + "\"")}", nameof(tools));
                }

                if (open.Element == null && skips.Count > 0)
                    Fail($"tool {r.Id}: open.element_skips names what an element door leaves out, and the row has none", nameof(tools));
                var types = open.ElementTypes;
                if (types != null && !AreTypeWords(types))
                    Fail($"tool {r.Id}: open.element_types is null or a non-empty list of distinct type words ({string.Join(", ", OWElementTypes.Slugs)}); got [{string.Join(", ", WordsAsWritten(types))}]", nameof(tools));
                if (open.Element == null && types != null)
                    Fail($"tool {r.Id}: open.element_types names what an element door opens, and the row has none", nameof(tools));
                if (r.Rung != OWTool.Listed) continue;
                if (audience == OWOpenerSurface.Public && needs == OWToolOpen.Device) continue;
                var template = kind == Element ? open.Element ?? open.World : open.World;
                if (template == null) continue;
                // An element door that cannot open this element is no door (a row with skips has one: refused above).
                if (kind == Element && marks.Exists(m => Contains(skips, m))) continue;
                // A tool that opens other kinds of element is no door for this one, and offers no world fallback either.
                if (kind == Element && types != null && !Contains(types, values["type"])) continue;
                // The first that holds. A word the row needs (it cannot open now) comes before "Opens the world" (it
                // opens, somewhere else), so a world door alone that needs a sign-in says the sign-in. With no
                // connection a web link opens nothing, whatever else it needs.
                var href = Placeholder.Replace(template, m => values[m.Groups[1].Value]);
                // What the row needs on this surface: a public page shows a public world, which a row that opens one
                // opens with nothing signed in.
                var need = audience == OWOpenerSurface.Public && open.OpensPublic ? null : needs;
                string state = null;
                if (tool != null && r.Client == tool) state = OWOpenerState.YouAreHere;
                else if (Offline(href)) state = OWOpenerState.NeedsAConnection;
                else if (audience == OWOpenerSurface.Public && need == OWToolOpen.Account) state = OWOpenerState.NeedsAnAccount;
                else if (need == OWToolOpen.Account && !surface.Browser) state = OWOpenerState.OpensInYourBrowser;
                else if (need == OWToolOpen.Account && surface.SignedIn == false) state = OWOpenerState.SignInFirst(r.Name);
                else if (need == OWToolOpen.Device && surface.Phone) state = OWOpenerState.NeedsTheWorldOnThisPhone;
                else if (kind == Element && open.Element == null) state = OWOpenerState.OpensTheWorld;
                rows.Add(new OWOpener(r.Id, r.Name, href, state));
            }

            // An element held in upper case: no rows, now that every row of the list has been checked.
            return unnamed ? new List<OWOpener>() : rows;
        }

        /// <summary>
        /// A template begins with its scheme (a browser drops leading spaces before reading one), and a scheme that opens
        /// no app is refused, in any case: a row whose link used one would run what it carries when pressed. Null is no door.
        /// </summary>
        private static void CheckTemplate(string row, string key, string template)
        {
            if (template == null) return;
            var m = Scheme.Match(template);
            if (!m.Success) Fail($"tool {row}: open.{key} begins with its scheme", "tools");
            var scheme = m.Groups[1].Value.ToLowerInvariant();
            if (Array.IndexOf(NoApp, scheme) >= 0) Fail($"tool {row}: open.{key} is a {scheme}: link, which opens no app", "tools");
        }

        private static void Fail(string what, string param) => throw new ArgumentException("OWOpeners.For: " + what, param);
    }
}
